) AS (
  VALUES 
    (214::BIGINT, 'Tiene calificación alta porque los demás profes son peores, pero no es este sea excelente. Las clases si son sencillas por sí solas, uno ya debe de ir con todos los pasos casi que aprendidos porque los pregunta al iniciar la clase. Califica extremadamente duro los informes y practicas'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Aspectos de calificación claros']::TEXT[], '2026-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'd249428155d54c2a3ce830472481f91feefeafb709a2fc7c02487b6d31bf75d8'::TEXT, ARRAY[607]::BIGINT[]),
    (214::BIGINT, 'es buena gente, hace los quices en el gaap pero si se pone un poco (mucho) exigente con los informes y reportes xd apesar de ser un laboratorio si quita mucho tiempo porque todo le gusta ordenado'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'b7ed7f04e7a5291891df6546c86ee7bc181ab81087e471e0b2349ebefddf5d0a'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'Es muy flexible y explica muy bien cosas que a otros profes le daría pereza explicar o dirían: "eso y alo tendrían que saber".'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-03T00:00:00+00:00'::TIMESTAMPTZ, '55bee370afd8bc1807daf0665aef3c826bdab1879295536414f1be3f1a412bd4'::TEXT, ARRAY[607]::BIGINT[]),
    (214::BIGINT, 'Explica muy bien y hace ejercicios muy útiles en clase, vale la pena matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2025-12-17T00:00:00+00:00'::TIMESTAMPTZ, 'a666311345ee6188b0891f781e4e7250215b8e09e2f3d0bb8d9c872faa14f6cf'::TEXT, ARRAY[922]::BIGINT[]),
    (214::BIGINT, 'Explica demasiado bien, hace muchos ejercicios. Hace varios quizzes que no son tan sencillos y cuestan como 5% c/u. No califica tan rudo exámenes. Siempre pasa lista eso sí. Recomendado, es facilito.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, '41dd4ec809a910f80f09907ec28228c16b519488acd04f217b7e4433e1b38003'::TEXT, ARRAY[922]::BIGINT[]),
    (214::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, '513fcd819c5f46cbc0c135bf8a61b7c014cc7e9525006d8492ff68b02cb6d39f'::TEXT, ARRAY[607]::BIGINT[]),
    (214::BIGINT, 'Buen profe la verdad, una buena persona es compresivo y explica bien lo recomiendo para este curso solo que el curso como tal requiere mucho tareas largas(pero así es por la catedra) que es medio molesto pero el profe califica bastante bien'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2025-12-05T00:00:00+00:00'::TIMESTAMPTZ, '5d7e7766c371bae20c5a0b177443da665e904e43dd06b078742e1a95e9e049c9'::TEXT, ARRAY[607]::BIGINT[]),
    (214::BIGINT, 'Hace ejercios en clase que son parecidos al examen y siempre esta dispuesto a contestar dudas en la hora de consulta.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2025-07-01T00:00:00+00:00'::TIMESTAMPTZ, '8ee5084dfdadbf44791fe4300e7197b06386efed52d8a9f75955d0c867ee919a'::TEXT, ARRAY[922]::BIGINT[]),
    (214::BIGINT, 'El profe es muy bueno pero el curso requiere bastante práctica. Se pierde bastante porcentaje en quizzes pero si usted se prepara todo bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-29T00:00:00+00:00'::TIMESTAMPTZ, '40f9cbacd89afa2825a240ef63cf0ee4d0ab2f03be2a0b2f78209fb43562fb44'::TEXT, ARRAY[922]::BIGINT[]),
    (214::BIGINT, 'El profe es muy bueno explicando y se nota que le gusta lo que hace, pero sí califica duro. Lo recomiendo bastante, solo que si tiene que tener la materia siempre presente para que en las evaluaciones no le vaya mal.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2025-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'c931699ab3be02a8d04ec25ce80f3c94d8fb5526480fbd8def5eec887070c8c6'::TEXT, ARRAY[922]::BIGINT[]),
    (214::BIGINT, 'Es buen profe y explica bastante claro. No regala puntos pero no lo considero necesario porque califica bastante suave.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, '6c2e9416ff1994028cc94eaef263092325ab76b1fe2a3db33189068ce1e63d41'::TEXT, ARRAY[922]::BIGINT[]),
    (214::BIGINT, 'La verdad no es mal profe. Pero si ya llevó antes física 2 NO MATRICULE CON ÉL. Explica de manera redundante, y desordenada haciendo que las clases sean difíciles de seguir para alguien que quiere que vaya al grano. Aún así es buena gente y se nota que le gusta la clase pero no lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2024-12-07T00:00:00+00:00'::TIMESTAMPTZ, '1ff0128d808085bfc3f7e08afad82f5a15d63a17b22ca5a4d4aeac77833a13d9'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'Es un buen profe, pero la cátedra no le ayuda. El mae explica bien y la vara, a veces se va un poco por las ramas, pero simepre trae la clase planeada en una notas y siempre las sigue. Califica justo y en consulta siempre le va ayudar. Las tareas que manda la cátedra es lo que hace el curso pesado.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, '0bc9fc2d6c517075fb8cefabc6045cb307c420c2c63ee8f48902310b9f46f58f'::TEXT, ARRAY[604]::BIGINT[]),
    (214::BIGINT, 'Es buen profe, sin embargo a veces explica demás por lo que a veces cuesta llevarle el hilo de la materia durante las clases. Pero en general es buen profe, califica justo los examenes y en las otras evaluaciones. Aunque los quices son algo pesados por que son 3, para un total de 18% de nota final.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2024-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'c9defd0cd50e9beec845535be88118357b6f23f53e87cc009e8396745e8a4e04'::TEXT, ARRAY[922]::BIGINT[]),
    (214::BIGINT, 'Es un buen profe, se preocupa por que uno entienda y da muchos ejercicios para que el estudiante aprenda bien y se prepare para los exámenes. Si califica duro, pero como profesor el cumple. Los quices son sencillos pero necesita estudiar porque son pocos y valen mucho.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Asistencia obligatoria']::TEXT[], '2024-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'bb45e1bfdbfd2418ef8de5ef87e76c1e621a11f1107662e48c339734d18051df'::TEXT, ARRAY[922]::BIGINT[]),
    (214::BIGINT, 'El profe es cómico y buena gente. Es bastante claro y trae la materia bien preparada con buenos ejemplos. Hace varios quices y evaluaciones pequeñas, entonces hay que estar estudiando. Califica justo. Recomendado.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-07-25T00:00:00+00:00'::TIMESTAMPTZ, '411675fab803fa56b1a3e2e62d58fec50f7dcda1b7b41e6684c42db3b61e7490'::TEXT, ARRAY[922]::BIGINT[]),
    (214::BIGINT, 'Excelentes clases, se nota que las prepara y los ejemplos de ejercicios que da en clase son bastante útiles. Siempre dispuesto a ayudar. Definitivamente matricularía de nuevo con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'bb9c237f75023fdd43c73b5f42c05568a44f00c832ea367a2f20f8f6ec0d578e'::TEXT, ARRAY[922]::BIGINT[]),
    (214::BIGINT, 'Explica muy bien, a pesar de que no pasa lista vaya siempre a clases porque a veces con las explicaciones que da es más que suficiente para el examen (lo digo por experiencia propia ), califica justo y aclara dudas siempre. Solamente hace 2 quices, uno antes de cada examen'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '0f01b5056edd80a6c71a806e20fe04b6e142dc2796e136a5ee8ac6b33d1ae07a'::TEXT, ARRAY[604]::BIGINT[]),
    (214::BIGINT, 'Es un profesor muy bueno, cómico, explica excelente, califica justo y no pasa lista. VAYA A CLASES, por mas que no sea obligatorio, no cometa el mismo error que yo jahjajaja. Siempre explica todo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '0014c91ef7ed3526e46b952e09f7461d534b7342bad70d22b58fee2520c94ad5'::TEXT, ARRAY[604]::BIGINT[]),
    (214::BIGINT, 'Buen profe, sabe un montón y se aprende bastante. Eso sí, hace muchos quices "sencillos" si estudió y califica duro los exámenes porque no le importa si el análisis es correcto, si falló un número y arrastró ese error, hasta ahí llegó. Es bueno al explicar, más no volvería a llevar el curso con él.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos exámenes']::TEXT[], '2024-06-04T00:00:00+00:00'::TIMESTAMPTZ, '1351a1b009c17cc37fbd61511a6d66148c113ec728947eb303330d4573cbb027'::TEXT, ARRAY[922]::BIGINT[]),
    (214::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-01-06T00:00:00+00:00'::TIMESTAMPTZ, '8504bd715463a5753f5c309445f09bbf0da2352226153b60892394caa5ba4360'::TEXT, ARRAY[604]::BIGINT[]),
    (214::BIGINT, 'Explica super claro y realiza muchos ejercicios en clase, se nota que le apasiona la enseñanza'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2023-12-13T00:00:00+00:00'::TIMESTAMPTZ, '65d2e4a40026f9ab967070f0407b4d684b4db76fcac93f4922910c014f41ae64'::TEXT, ARRAY[604]::BIGINT[]),
    (214::BIGINT, 'Excelente profe, hace las clases muy amenas, está súper pendiente de los estudiantes, siempre dispuesto a ayudar y resolver dudas. Es muy comprensivo, califica de forma justa y va al día con las evaluaciones. El horario de consulta es provechoso e incluso se esfuerza por encontrar espacios extra.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'd361ebade1931e6258eb7368723575516a81c7a15bf652eca65b4490facb762e'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'Considero que es uno de los mejores profes, le importa mucho que el estudiante comprenda y exprese su entendimiento. Vaya a consulta, él siempre estará dispuesto a ayudar y en serio que ayuda. Sus indicaciones siempre son claras.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '3750299926591e9ff46827d774bc24fbfea79a62b009725429efd2dbf7e4d01d'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'Excelente profesor siempre dispuesto a ayudar a los estudiantes, las clases se entienden muy bien y lleva todas las notas al día, matriculé con él sin miedo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '290fe83b49e872157e7caffab10b94e572986f0272ed8c724f11f05085c95c2a'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'Excelente profesor. Tiene un dominio muy alto de los temas. Aclara todas las dudas siempre de la mejor manera. Califica de forma justa y da retroalimentación clara para mejorar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, '0639180a819cd72fe440c8e092f02f5123068a9e152bb2011e3b025b2594cdef'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'Considero que el profe es excelente a nivel pedagógico, explica súper bien y se le nota la pasión y gran conocimiento que posee de los temas. Es súper buena persona y lo recomiendo full. El curso es difícil, pero él siempre está dispuesto ayudar.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-03T00:00:00+00:00'::TIMESTAMPTZ, 'c87450b201ee50a63274a62f47fef5a5070b37e743c672aa2a78ae5b020012ac'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'Es una teja de profe. Hace que uno se interese en las clases y, a pesar de ser un curso pesado, hace que sea llevadero. Para mí, uno de los mejores profes de Física II. Recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '3f73636807153ecc27bdf7bb2d594e9fa19136bd319f9f7f8ed4607dbb802ca2'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'Excelente profesor, da las clases de manera que los estudiantes también se interesen y fomenta la participación para generar discusiones del tema, aclara cualquier duda e incita a que preguntemos. Los quices y tareas de cátedra son duros eso sí, entonces con sus clases realmente no basta.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, '9abf48d4209a385dd8ca8d8d95877d9ccccc6d3989fe31ddd3f18c0245bbbdc3'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'El profe es super buena nota, las clases son muy entretenidas y hace que exista un ambiente de confianza hasta para bromear con él. Califica un poco duro.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Brinda apoyo']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'ea7e66afc60c6eb7c1c8beb5a46a4579134095724463f01e6af4ee30605fd869'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-04-07T00:00:00+00:00'::TIMESTAMPTZ, 'd066d4116dc63c3775ea06595edebfe23d990ea0a8a70a1f3e2dc20e97278518'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'De los mejores profes de la escuela de física, explica demasiado bien y se preocupa por que uno aprenda. El tec digital es una belleza con apartados de los videos de las clases y sus presentaciones por si falta o quiere repasar de manera sencilla. Super recomendado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'bf0a2f684df9361ced0522edbd76b08f8b49700d56b0e90206338ff15cf20968'::TEXT, ARRAY[922]::BIGINT[]),
    (214::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, '6a3f638e481d363d4cbf2c26b6f83e1c2803cacd075137ed6a3efe8ff83bf2ba'::TEXT, ARRAY[607]::BIGINT[]),
    (214::BIGINT, 'EXCELENTE profesor!! Explica súper claro todo el contenido y siempre está pendiente de dudas. La retroalimentación de los trabajos es muy valiosa y se aprende bastante!! Las notas siempre se mantienen actualizadas. Las clases son motivadoras y interactivas. 10/10. No dude en matricular con él!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, '4037ce35b5a62599600678d5ecf6614b99d2d7cebdf2dd9339ccbb0ebb2add15'::TEXT, ARRAY[607]::BIGINT[]),
    (214::BIGINT, 'De lo único que me arrepiento este semestre, es de casi no haber asistido a sus clases, porque eran muy entretenidas y brindaba apoyo para hacer las tareas. El profe es muy apasionado por lo que hace y vuelve la materia super interesante. Sin duda el mejor profe de física.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, '45c0fd46d09d0f7ace5da400a877d3d0d31138721d12d12a6228b3f45279229a'::TEXT, ARRAY[922]::BIGINT[]),
    (214::BIGINT, 'A decir verdad, lo cansado se convierte en la forma en la que está estructurada el curso porque es de 1 crédito y muchas veces dejan trabajos que consumen hasta 2 días enteros, pero por parte del profesor, es muy bueno.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, '92f13ed32f0e8bb79aede3f1184496cd9614e21859504ea17bb8f8d829d928e8'::TEXT, ARRAY[607]::BIGINT[]),
    (214::BIGINT, 'Es muy buen profe, califica justo y explica bien. No le va a regalar el curso. Algo malo es que sólo responde dudas en la hora de consulta.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2021-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'd15f12aba6ef4ff354b4a0461ec04ee6faf79a089ee2444f870ce333037e5156'::TEXT, ARRAY[607]::BIGINT[]),
    (214::BIGINT, 'El profe es excelente si a usted se le dificulta el curso, explica de forma clara y la cantidad de veces que sea necesario, siempre es muy paciente. Las clases son muy pesadas pero él las hace interesantes.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '9bf48920b3b38da0265b6bf04c946d05f77e7ec035dec3bd24540fb744efcca5'::TEXT, ARRAY[922]::BIGINT[]),
    (214::BIGINT, 'Las clases son muy densas en materia, pero explica excelente, aclara todo en clase y afuera de clase, califica justo, y en general hace la clase sumamente interesante. Para los trabajos da muy buena retroalimentación y explica excelente lo que espera de cada uno de ellos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'e2bbe49f2d8772bab470dac84a42fa62963e724b7b3e726e44b4b2e46fe112c5'::TEXT, ARRAY[922]::BIGINT[]),
    (214::BIGINT, 'Es un profesor que sabe bastante sobre la materia. Se enfoca en ejercicios que abarcan bastantes aspectos de los temas que se ven para que a la hora de las evaluaciones se puedan resolver de manera correcta. Las clases se pueden volver un poco aburridas y largas. Es comprensivo con evaluaciones.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Brinda apoyo']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '5aea5fad9ac21699091c3b8f7d08a1e5b66a00f6b772a748fe64853b10deb72c'::TEXT, ARRAY[922]::BIGINT[]),
    (214::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2021-02-16T00:00:00+00:00'::TIMESTAMPTZ, 'd552fe650dd15477854a116b0ed11dc0b7511845f6a06b92892d86590811ea44'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'Super recomendado, excelente profesor, explica muy bien, aclara todas las dudas que tenga y es super atento y buena gente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '8eb73406b84fb41c527c56b6996cf8f8d79b426ab2b467907519d480cba0e882'::TEXT, ARRAY[922]::BIGINT[]),
    (214::BIGINT, 'Explica super bien, da feedback claro, siempre dispoible para ayudar. Si la ve fea con alguna fecha de entrega, trate de avisarle al profe con tiempo, él es de los que sí comprenden'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'eb10cdc6432593dc9188d171dc9f42a4ddc3578965d1bd5816cab25907f146b7'::TEXT, ARRAY[922]::BIGINT[]),
    (214::BIGINT, 'Muy buen profe y persona, se asegura que todos aprendan e intenta hacer las clases más amenas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'fa336ffb27245e6bc15b28a3b5f950994ed24924e7ea35611084bfcf2acc8742'::TEXT, ARRAY[922]::BIGINT[]),
    (214::BIGINT, '[VIRTUAL] Buen profe, siempre atento a las consultas, califica bien y en algunos casos deja tiempo extra para los entregables.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-04T00:00:00+00:00'::TIMESTAMPTZ, '5f7fe3e302b5a7371b788319963247573b8dc3a22f7ab3c28d022f104e3c1968'::TEXT, ARRAY[922]::BIGINT[]),
    (214::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-12-19T00:00:00+00:00'::TIMESTAMPTZ, '755b9c7eec166f036158d02e4df5baf01a3272c7576de5374a8df058640cd460'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'Explica muy bien. Atiende todas las dudas por correo o telegram cualquier día a cualquier hora e incluso hace una vídeo llamada para ayudar con la comprensión de los temas que no quedaron claros de ser necesario. Califica un poco duro pero justo. En resumen excelente profe.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '48775e7d1ebf52f2f53df14ca64aa4db0d3e8d4c3ec0d84a6f21e5575531ceda'::TEXT, ARRAY[607]::BIGINT[]),
    (214::BIGINT, 'Laboratorio de Física I virtual: Si uno tiene dudas siempre las aclara, incluso si es necesario una video llamada para explicar mejor. O bien, si necesita más tiempo para entregar informes o trabajos no tiene problema en dar tiempo extra.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '443e9c486d4261cc6ce440830f653eb879600e1cc8bbfa441f1b94030066a42a'::TEXT, ARRAY[607]::BIGINT[]),
    (214::BIGINT, 'Terrible, que profe mas creído, solo dañar al estudiante, no se lo recomiendo, ademas demasiadas evaluaciones'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-22T00:00:00+00:00'::TIMESTAMPTZ, '636be52f42958aee51d2752c63f38502074e9fb4a9f7dd025cd4e0e6e2cf934a'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-02-11T00:00:00+00:00'::TIMESTAMPTZ, '6b6cc25d32a5d0e83008b6dae51b367d3498fc269148d819b97ee06e8a938644'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'Es bueno explicando, se nota que sabe un montón y a veces hasta es chistoso; pero se cree demasiado. A veces anda de malas y responde súper repugnante o incluso hasta ignora la pregunta. Lo recomiendo si uno es ultra pipa, sino matricule con otro que él no es la última coca del desierto.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-29T00:00:00+00:00'::TIMESTAMPTZ, '8b4ebb9cb4f752a590c9f55bea9058b824f05485fca73185b4948eb99790c9de'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'Este semestre estaba extraño, para aclarar dudas no era muy accesible.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-12-19T00:00:00+00:00'::TIMESTAMPTZ, '839ec8bd3a6b7b24042d0cea8644fa1c4e92005040989ea0aeff153f923a119d'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'Sin duda el mejor profe de Física. No dude en matricular con él, se le nota la pasión por enseñar y le transmite ese sentimiento a los estudiantes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-27T00:00:00+00:00'::TIMESTAMPTZ, '4328344c0aa1e3c5c27d1df6d11c45ddbe7b408d0f412a3d753caf909cc3c450'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'El profesor más crecido que he tenido, si si si todo bien, es profe de física pero bájenlo de esa nube que al contestar preguntas es un repugnante. Demasiados trabajos durante el semestre, califica muy duro por erorres mínimos y según él no quiere “joder” al estudiante, y es lo único que hace'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, '809c10f4adbdb2beb8195c928595cebcd77d03e81584bb2708a4cdb741742db5'::TEXT, ARRAY[922, 604]::BIGINT[]),
    (214::BIGINT, 'Coincido con el comentario de abajo: El peor profe de la vida, juega mucho de profe cool pero nada que ver, va por el mismo camino de todos los profes de física a joder el estudiante. Lo intenta pero no lo logra, arrogante para aclarar dudas en clases. No lo recomiendo, Afecta mucho al estudiante'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, '6369df434a84d648c75161568c0244583a2cb63030197365ad7b62a2ddd90327'::TEXT, ARRAY[922, 604]::BIGINT[]),
    (214::BIGINT, 'Es demasiado bueno, explica súper claro, es cómico, y contagia el amor por la física. Califica suave y en el porcentaje de tareas y quices ayuda bastante si uno trabaja y entrega todo. Pone a hacer práctica a los estudiantes ahí en clase, eso no me gustó mucho.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2019-11-25T00:00:00+00:00'::TIMESTAMPTZ, '323d7d2c80d30ddf71487a0acd77ad939ae23df530172c4ff11ae59fadc54cf8'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'Si tiene la oportunidad de matricular con él no lo dude, es demasiado bueno y ayuda bastante en como califica. La materia de fisica ll es ruda, entonces no se puede esperar que todo el curso sea fácil, pero es un profesor demasiado bueno que busca ayudar al estudiante.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '1c14dcb0da9ebb0a46004284913700f72530294a42c05d701813344162797d3d'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'El peor profe de la vida, juega mucho de profe cool pero nada que ver, va por el mismo camino de todos los profes de física a joder el estudiante. Un vuitre como dice el.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '24a8c1fcc1cfd12e32e8ddeea738c563f261f7a34adc59000e215f780e5d2bbb'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'Explica muy bien, hace trabajos que ayudan a conseguir puntos y califica muy suave. Es medio atarantado así que hay que prestar atención toda la clase para no perderse.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Aspectos de calificación claros']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, '77ccc718437cc3c2579afe382bc8124923acfffedb1a7734d9aae3b33fbe19cb'::TEXT, ARRAY[631]::BIGINT[]),
    (214::BIGINT, 'Muy pura vida, explica muy bien y no califica muy duro. Siempre busca ayudarlo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-27T00:00:00+00:00'::TIMESTAMPTZ, '645fd629c76452c9d148e0e3378d457ea963e46fbaa8eef5e2dea3b02f237a7a'::TEXT, ARRAY[607]::BIGINT[]),
    (214::BIGINT, 'El mae explica muy bien pero también es bastante exigente con los informes, si tiene un buen grupo de trabajo no se hace tan pesado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2019-01-21T00:00:00+00:00'::TIMESTAMPTZ, '2d8467dd060ff266ddfb87805b833faf6dba0adeea4f18fdd9a20509e07b7899'::TEXT, ARRAY[607]::BIGINT[]),
    (214::BIGINT, 'Es el PUTO AMO de la Física.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, '3f212de9acf502564d8e531c9d9a53bddb38aaf81ceeb1535449a7a821ef68bf'::TEXT, ARRAY[604]::BIGINT[]),
    (214::BIGINT, 'Es un meme andante, habla raro, demasiado pura vida. Se hace ver demasiado chill, pero califica durillo, cuidado con eso, tiene que hacer los trabajos muy bien. Pero en sí es fácil. No nos hizo ni un solo quiz ni había que llevar prerreporte.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-23T00:00:00+00:00'::TIMESTAMPTZ, '7979edd8e5990ca136c10e271076975d791bb28a92f39d80243f5a4d5e2d65aa'::TEXT, ARRAY[607]::BIGINT[]),
    (214::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-11-11T00:00:00+00:00'::TIMESTAMPTZ, 'a63f252357110fe439246edd0167f6f6630ac12a59cff511ce3d35127f4c3ec6'::TEXT, ARRAY[604]::BIGINT[]),
    (214::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2018-06-12T00:00:00+00:00'::TIMESTAMPTZ, '2465b4bcb9af772af432ff73ff08b05c160a1b015d5426731cf6bc4da5b8b28f'::TEXT, ARRAY[922, 604]::BIGINT[]),
    (214::BIGINT, 'Richie ama dar la clase, ama la materia y le encanta ver al estudiante emocionado con él. Le gusta que todos entiendan y hace de la Física algo accesible para los que tienen algo de dificultad comprendiéndola.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-02-14T00:00:00+00:00'::TIMESTAMPTZ, 'a92e9d58fbfd51052da45432c07ee5654ccc983ef52d89766876d143ad1ec114'::TEXT, ARRAY[1369]::BIGINT[]),
    (214::BIGINT, 'Ya había dicho que es un excelente profe para física 1, y lo reafirmo con física 4.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'd2b355aec2deb2d8edde8907f0f9c74aaa8f5b526f5cbe577e8ff7ec50beabc4'::TEXT, ARRAY[1369]::BIGINT[]),
    (214::BIGINT, 'Excelente profesor . Tiene vocación por enseñar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-02-06T00:00:00+00:00'::TIMESTAMPTZ, '97ab789aa01c5f0db4c9d30fa31416d6f42af3d1dedcc810dedb6e32d037c6e5'::TEXT, ARRAY[922, 604]::BIGINT[]),
    (214::BIGINT, 'Muy recomendado. Explica super claro y las veces que se necesite. Dispuesto a ayudarlo en lo que pueda, además sus clases son muy entretenidas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-26T00:00:00+00:00'::TIMESTAMPTZ, '63eaf0bccc563d61d0a3d9e72f9d90405631a1c0cb2d2196902f55e22e943eec'::TEXT, ARRAY[607]::BIGINT[]),
    (214::BIGINT, 'Fui de oyente con este individuo, este mae es un DIOS de la Física, un profe que logra inyectarle a uno esas ganas de estudiar. Se va rapidito jaja'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'a5a48284cf3527d357984115d6c1ed20d890e836ca53607530a0915c8f09916d'::TEXT, ARRAY[604]::BIGINT[]),
    (214::BIGINT, 'Cae de lo más bien. Es súper claro y está dispuesto a explicar cuántas veces sea necesario. A veces pierde mucho tiempo demostrando fórmulas y no hace muchos ejercicios en clase. Hay que hacer siempre las tareas y poner atención.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-26T00:00:00+00:00'::TIMESTAMPTZ, '45e3a7c156285412cf5dcaabc834cbca2ae0ec0cf0c8b14d88725f94fdbbb2d4'::TEXT, ARRAY[604]::BIGINT[]),
    (214::BIGINT, 'Un profesor genial. Aparte de ser muy bueno como profesional, estará dispuesto a ayudarte en todo cuanto se le pida ayuda. Como persona excelente: amigable, gentil y dispuesto. Dando clases se esfuerza para que todos entiendan, es muy claro y ayuda montones.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-11T00:00:00+00:00'::TIMESTAMPTZ, '9d763ea6c3a6febd8aa06ee3acf95021bb0ef7c7645f112146f82e6266eabdad'::TEXT, ARRAY[607]::BIGINT[]),
    (214::BIGINT, 'El mejor profe que tiene la escuela de física, super pura vida, explica super bien, aclara cualquier duda, es super accesible y ayuda un montón al final del curso'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-30T00:00:00+00:00'::TIMESTAMPTZ, '4a79df4ce5a0131ca1be0a3d76c7915f750246accc181872f6f0c9cb86f041e8'::TEXT, ARRAY[604]::BIGINT[]),
    (214::BIGINT, 'Excelente profesor, es muy claro cuando explica y hace varios ejemplos en clases. Explica hasta que todos entiendan. Se le nota que le gusta enseñar y como persona también es exc! Hace que las clases sean muy entretenidas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-28T00:00:00+00:00'::TIMESTAMPTZ, '9b2599efb3453a243e5ef74af36480f1a88fd53b93c5d015682c885458a160c9'::TEXT, ARRAY[604]::BIGINT[]),
    (214::BIGINT, 'Muy buen profesor, explica muy claro, atiende cualquier duda. Es un poco exigente en cuanto a trabajos y proyecto. Pero muy recomendado.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, '4c81df7a3afbd084fd7cd4c3049405f3a8dc98c931d1e34c0becab10adea88de'::TEXT, ARRAY[607]::BIGINT[]),
    (214::BIGINT, 'Excelente profe de lab. Hace presentaciones para explicar que luego las comparte. Es muy claro con la explicación. Como persona es genial, muy divertido, y se identifica con sus estudiantes. Hace la clase muy amena. Recomendado, es el mejor para el laboratorio'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-21T00:00:00+00:00'::TIMESTAMPTZ, '3d931ebe65a8e32a10d0ea944464320de21acbd7a1254cc5f2b62e5677ee6148'::TEXT, ARRAY[607]::BIGINT[]),
    (214::BIGINT, 'Muy buen profesor, se le entiende todo y responde a todas las preguntas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-18T00:00:00+00:00'::TIMESTAMPTZ, '055a05cce3862913c7d501ada26c44d5fcb9b2d3054bcd502844ca7bf54950e2'::TEXT, ARRAY[922, 604]::BIGINT[]),
    (214::BIGINT, 'Es muy buena nota. No tenga miedo de preguntar cualquier tontera con mucha amabilidad le aclarará la duda. Da muchos ejemplos en clase. Califica justo. Es gracioso en clase. Domina bien la materia, solo que va muy rápido. Sugerencia, lo que el explica en la clase llegar a repasarlo del libro.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-17T00:00:00+00:00'::TIMESTAMPTZ, '446550c9d034b62eace19fa554170cca22828c416ff5c3d51d29c5d3f2adf695'::TEXT, ARRAY[604]::BIGINT[]),
    (214::BIGINT, 'Muy buen profe, explica muy bien y da muchos ejemplos, se preocupa porque uno entienda todo. Aunque aveces ve la materia un poco rapido, pero en general excelente, a parte se lleva muy bien con los estudiantes'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-06T00:00:00+00:00'::TIMESTAMPTZ, '5d2f8ce51e4c4e1fe822a06be0bb7e404ec760b30e06eb325d16d2ca9fb19c9a'::TEXT, ARRAY[604]::BIGINT[]),
    (214::BIGINT, 'Muy buena persona, se lleva mucho con los estudiantes, es gracioso y lo más importante, muy buen profe. Siempre atiende dudas. El único problema es que explica muy rápido.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-25T00:00:00+00:00'::TIMESTAMPTZ, '1895cfdb8cfb1d4504b2819ea7a3b21b6753fcfecdce13439432ba8d717567a0'::TEXT, ARRAY[604]::BIGINT[]),
    (214::BIGINT, 'Explica bien, y se toma el tiempo para que el estudiante entiende, incluso aclara dudas por correo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'adc32c616402e1b6dd6dafae0818d0824be49ca4b62e0a7c0dd4d936afae6ae2'::TEXT, ARRAY[604]::BIGINT[]),
    (214::BIGINT, 'Explica muy bien. Dominio de los temas. Recomendado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-12T00:00:00+00:00'::TIMESTAMPTZ, '3dff3928563597858cf0db803ec683a5d54da594d9a2eab7b21f55a26218e4b6'::TEXT, ARRAY[604]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
